// ATS score for THIS item (0-100). Advisory only; it does not change the tier.
const src = $('Prepare Resume').item.json;
const resume = String(src.resume_text || '');
const norm = (s) => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const text = norm(resume);

// ---- 1. Keyword match (60 pts) ----
const STOP = new Set(['years','year','experience','with','and','the','of','in','to','a','an','strong','good','knowledge','proficiency','proficient','working','understanding','ability','skills','basic','using','for','or','on','plus','least','minimum','familiarity','hands']);
const parseList = (s) => String(s || '')
  .split(/[\n,;•·\u2022]|\s-\s/)
  .map(x => x.replace(/^[\s\-*\d.)]+/, '').trim())
  .filter(Boolean);

const scoreTerm = (term) => {
  const t = norm(term);
  if (!t) return null;
  if (text.includes(t)) return 1;                       // exact phrase found
  const words = t.split(/[^a-z0-9+#.]+/).filter(w => w.length >= 3 && !STOP.has(w));
  if (!words.length) return 0;
  const hit = words.filter(w => text.includes(w)).length; // partial credit by word
  return hit / words.length;
};

const mustTerms = parseList(src.must_haves);
const niceTerms = parseList(src.nice_to_haves);
const missing = [];
let earned = 0, possible = 0;

for (const t of mustTerms) {
  const s = scoreTerm(t); if (s === null) continue;
  earned += s * 2; possible += 2;
  if (s < 0.5) missing.push(t);
}
for (const t of niceTerms) {
  const s = scoreTerm(t); if (s === null) continue;
  earned += s; possible += 1;
}
const keywordPts = possible ? Math.round((earned / possible) * 60) : 0;

// ---- 2. Sections (20 pts) ----
const sectionChecks = [
  { name: 'experience', re: /\b(work experience|professional experience|experience|employment)\b/, pts: 6 },
  { name: 'education',  re: /\b(education|academic|qualification)/, pts: 5 },
  { name: 'skills',     re: /\b(skills|technical skills|technologies|tech stack)\b/, pts: 5 },
  { name: 'summary or projects', re: /\b(summary|objective|profile|projects)\b/, pts: 4 },
];
let sectionPts = 0;
const issues = [];
for (const s of sectionChecks) {
  if (s.re.test(text)) sectionPts += s.pts;
  else issues.push(`no ${s.name} section found`);
}

// ---- 3. Contact info (10 pts) ----
const hasEmail = /[\w.+-]+@[\w-]+\.[\w.-]+/.test(resume);
const hasPhone = /(\+?\d[\d\s().-]{8,}\d)/.test(resume);
const contactPts = (hasEmail ? 5 : 0) + (hasPhone ? 5 : 0);
if (!hasEmail) issues.push('no email address found');
if (!hasPhone) issues.push('no phone number found');

// ---- 4. Readability (10 pts) ----
const wordCount = text ? text.split(' ').length : 0;
const badChars = (resume.match(/[\uFFFD\u0000-\u0008\u000E-\u001F]/g) || []).length;
const garbled = resume.length > 0 && badChars / resume.length > 0.02;
let readPts = 10;
if (wordCount < 150) { readPts -= 6; issues.push('very little text extracted (scanned or image-only PDF?)'); }
else if (wordCount > 1500) { readPts -= 3; issues.push('very long resume (over 1500 words)'); }
if (garbled) { readPts -= 4; issues.push('garbled characters in extracted text'); }
readPts = Math.max(0, readPts);

const total = Math.min(100, keywordPts + sectionPts + contactPts + readPts);
const rating = total >= 75 ? 'good' : total >= 50 ? 'fair' : 'poor';
const parseReliable = wordCount >= 150 && !garbled;

return {
  json: {
    ...$json,
    ats_score: total,
    ats_rating: rating,
    ats_breakdown: `keywords ${keywordPts}/60, sections ${sectionPts}/20, contact ${contactPts}/10, readability ${readPts}/10`,
    ats_missing_keywords: missing.join(', '),
    ats_format_issues: issues.join('; '),
    ats_parse_reliable: parseReliable,
  },
};
